<div class="page-head"><div><div class="page-kicker">Access control</div><h1 class="page-title"><?=esc($title)?></h1><p class="page-subtitle">Role describes the user; permissions determine what they can actually do.</p></div><div class="head-actions"><a class="btn" href="<?=site_url('users')?>">← Back to users</a></div></div>
<div class="card form-card"><form method="post" action="<?= $user ? site_url('users/'.$user['id'].'/update') : site_url('users/store') ?>"><?=csrf_field()?><div class="form-grid"><div class="field"><label>Full name</label><input name="name" value="<?=esc(old('name',$user['name']??''))?>" required></div><div class="field"><label>Username</label><input name="username" value="<?=esc(old('username',$user['username']??''))?>" required></div><div class="field"><label>Email</label><input type="email" name="email" value="<?=esc(old('email',$user['email']??''))?>"></div><div class="field"><label>Password</label><input type="password" name="password" <?= $user?'':'required'?> minlength="6" autocomplete="new-password"><div class="hint"><?=$user?'Leave blank to keep the current password.':'Minimum 6 characters.'?></div></div><div class="field full"><label>Base role</label><select name="role"><option value="user" <?=old('role',$user['role']??'user')==='user'?'selected':''?>>Inventory / Store User</option><option value="security" <?=old('role',$user['role']??'')==='security'?'selected':''?>>Security Guard</option><option value="owner" <?=old('role',$user['role']??'')==='owner'?'selected':''?>>Owner / Approver</option><option value="admin" <?=old('role',$user['role']??'')==='admin'?'selected':''?>>Administrator</option></select></div></div><div style="margin-top:25px"><div class="section-head" style="padding:0 0 14px;border-bottom:0"><div><h2 class="section-title">Permissions</h2><div class="section-meta">Select only the capabilities this person needs.</div></div><button type="button" class="btn small" data-select-all>Select all</button></div><div class="grid grid-3" id="permission-grid"><?php foreach($permissions as $key=>$label): ?><label class="card" style="padding:12px;cursor:pointer;display:flex;gap:10px;align-items:flex-start"><input style="margin-top:2px" type="checkbox" name="permissions[]" value="<?=esc($key)?>" <?=in_array($key,old('permissions',$selectedPermissions??[]),true)?'checked':''?>> <span><strong style="font-size:12px;display:block"><?=esc($label)?></strong><span class="muted" style="font-size:10px"><?=esc($key)?></span></span></label><?php endforeach; ?></div></div><div class="form-actions"><a class="btn" href="<?=site_url('users')?>">Cancel</a><button class="btn primary" type="submit"><?= $user?'Save changes':'Create user' ?></button></div></form></div>
<script>document.querySelector('[data-select-all]')?.addEventListener('click',()=>document.querySelectorAll('#permission-grid input[type=checkbox]').forEach(x=>x.checked=true));</script>
